import{_ as i,c as t,o as l,ae as a}from"./chunks/framework.DMK_uHmU.js";const r="/help-center/assets/blueprint-manager.CKtetlWP.png",n="/help-center/assets/blueprint-new.BgzaHEN3.png",b=JSON.parse('{"title":"AI Blueprint Manager Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Blueprints/blueprint-list-view.md","filePath":"Administration/AI-Management/Blueprints/blueprint-list-view.md"}'),o={name:"Administration/AI-Management/Blueprints/blueprint-list-view.md"};function s(u,e,p,h,c,d){return l(),t("div",null,e[0]||(e[0]=[a('<h1 id="ai-blueprint-manager-guide" tabindex="-1">AI Blueprint Manager Guide <a class="header-anchor" href="#ai-blueprint-manager-guide" aria-label="Permalink to &quot;AI Blueprint Manager Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Blueprint Manager provides a comprehensive interface for administrators to create, view, edit, and manage AI Blueprints. Blueprints define how the AI assistant behaves, what knowledge it can access, and how it interacts with users. This guide covers how to effectively use the Blueprint Manager to organize and maintain your AI experiences.</p><h2 id="accessing-blueprint-manager" tabindex="-1">Accessing Blueprint Manager <a class="header-anchor" href="#accessing-blueprint-manager" aria-label="Permalink to &quot;Accessing Blueprint Manager&quot;">​</a></h2><p>The Blueprint Manager is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component, navigate to <code>/blueprint/BlueprintListView</code> in the system. You&#39;ll typically find a link to this page in the administration menu or AI configuration section.</p><h2 id="blueprint-manager-interface-overview" tabindex="-1">Blueprint Manager Interface Overview <a class="header-anchor" href="#blueprint-manager-interface-overview" aria-label="Permalink to &quot;Blueprint Manager Interface Overview&quot;">​</a></h2><p>The Blueprint Manager consists of these key components:</p><p><img src="'+r+'" alt="homepage"></p><ol><li><strong>Header Section</strong>: Contains the title &quot;Blueprint Manager&quot; with blueprint count badge, description, and Add Blueprint button</li><li><strong>Search and Filter Controls</strong>: Tools for finding specific blueprints including global search, topic filter, and feature filter</li><li><strong>Data Table</strong>: Displays blueprint information in a sortable, filterable table</li><li><strong>Action Buttons</strong>: Quick access to refresh data, clear filters, and export to Excel</li><li><strong>Blueprint Editor</strong>: Full-screen dialog for creating and editing blueprints</li></ol><h2 id="viewing-blueprints" tabindex="-1">Viewing Blueprints <a class="header-anchor" href="#viewing-blueprints" aria-label="Permalink to &quot;Viewing Blueprints&quot;">​</a></h2><h3 id="blueprint-list-view" tabindex="-1">Blueprint List View <a class="header-anchor" href="#blueprint-list-view" aria-label="Permalink to &quot;Blueprint List View&quot;">​</a></h3><p>The main interface displays all blueprints in a tabular format with key information:</p><ol><li><strong>Blueprint Icon</strong>: Visual indicator for blueprint type</li><li><strong>Name and Description</strong>: Primary identifier and explanatory text for each blueprint</li><li><strong>Group Associations</strong>: Visual representation of groups with access to this blueprint</li><li><strong>Topic</strong>: Categorization label for the blueprint</li><li><strong>Features</strong>: Status indicators for key blueprint settings</li><li><strong>Update Information</strong>: Details about when and by whom the blueprint was updated</li></ol><h3 id="blueprint-information-display" tabindex="-1">Blueprint Information Display <a class="header-anchor" href="#blueprint-information-display" aria-label="Permalink to &quot;Blueprint Information Display&quot;">​</a></h3><p>Each blueprint entry shows comprehensive information:</p><ol><li><strong>Blueprint Name</strong>: The primary identifier (shown in bold)</li><li><strong>Status Indicator</strong>: &quot;Disabled&quot; badge appears for inactive blueprints</li><li><strong>Description</strong>: Text explaining the blueprint&#39;s purpose</li><li><strong>Tags</strong>: Small badges showing associated tags for categorization</li></ol><h3 id="blueprint-features-indicators" tabindex="-1">Blueprint Features Indicators <a class="header-anchor" href="#blueprint-features-indicators" aria-label="Permalink to &quot;Blueprint Features Indicators&quot;">​</a></h3><p>The Features column uses visual indicators to show enabled settings:</p><ol><li><strong>Secure</strong>: Green indicator when the blueprint has security settings enabled</li><li><strong>Home Screen</strong>: Green indicator when the blueprint appears on the home screen</li><li><strong>Quick List</strong>: Green indicator when the blueprint appears in quick selection menus</li></ol><h2 id="searching-and-filtering-blueprints" tabindex="-1">Searching and Filtering Blueprints <a class="header-anchor" href="#searching-and-filtering-blueprints" aria-label="Permalink to &quot;Searching and Filtering Blueprints&quot;">​</a></h2><h3 id="global-search" tabindex="-1">Global Search <a class="header-anchor" href="#global-search" aria-label="Permalink to &quot;Global Search&quot;">​</a></h3><p>The global search field searches across multiple blueprint fields:</p><ul><li>Blueprint name</li><li>Description</li><li>Topic tags</li><li>Author information</li></ul><p>Enter text in the search box to instantly filter the list to matching blueprints.</p><h3 id="topic-filtering" tabindex="-1">Topic Filtering <a class="header-anchor" href="#topic-filtering" aria-label="Permalink to &quot;Topic Filtering&quot;">​</a></h3><p>To filter blueprints by topic category:</p><ol><li>Click the &quot;Topic&quot; button to open the topic selection menu</li><li>Select a specific topic from the list to filter blueprints</li><li>Only blueprints with the selected topic will be displayed</li><li>Click &quot;Remove Filter&quot; to clear the topic filter</li></ol><h3 id="feature-filtering" tabindex="-1">Feature Filtering <a class="header-anchor" href="#feature-filtering" aria-label="Permalink to &quot;Feature Filtering&quot;">​</a></h3><p>To filter blueprints by feature settings:</p><ol><li>Use the &quot;Features&quot; multi-select dropdown</li><li>Select any combination of: <ul><li>&quot;Secure&quot; - Shows only blueprints with secure mode enabled</li><li>&quot;Home Screen&quot; - Shows only blueprints displayed on the home screen</li><li>&quot;Quick List&quot; - Shows only blueprints in the quick selection list</li></ul></li><li>The filter applies immediately, showing only blueprints with all selected features enabled</li></ol><h3 id="group-filtering" tabindex="-1">Group Filtering <a class="header-anchor" href="#group-filtering" aria-label="Permalink to &quot;Group Filtering&quot;">​</a></h3><p>To filter blueprints by associated groups:</p><ol><li>Click the filter icon in the Groups column header</li><li>Select a group from the dropdown</li><li>Only blueprints assigned to that group will be displayed</li></ol><h3 id="clearing-filters" tabindex="-1">Clearing Filters <a class="header-anchor" href="#clearing-filters" aria-label="Permalink to &quot;Clearing Filters&quot;">​</a></h3><p>When filters are active, a &quot;Filter On&quot; indicator appears, and the filter slash button turns blue.</p><p>To clear all active filters:</p><ol><li>Click the &quot;Filter Slash&quot; button</li><li>All filters will be reset to their default state</li><li>The complete blueprint list will be displayed</li></ol><h2 id="managing-blueprints" tabindex="-1">Managing Blueprints <a class="header-anchor" href="#managing-blueprints" aria-label="Permalink to &quot;Managing Blueprints&quot;">​</a></h2><h3 id="creating-blueprints" tabindex="-1">Creating Blueprints <a class="header-anchor" href="#creating-blueprints" aria-label="Permalink to &quot;Creating Blueprints&quot;">​</a></h3><p>To create a new blueprint:</p><p><img src="'+n+'" alt="homepage"></p><ol><li>Click the &quot;Add&quot; button in the top-right corner</li><li>The Blueprint Editor dialog will open</li><li>Configure the blueprint settings across the available tabs</li><li>Click &quot;Save&quot; to create the blueprint</li><li>The new blueprint will appear in the list</li></ol><h3 id="editing-blueprints" tabindex="-1">Editing Blueprints <a class="header-anchor" href="#editing-blueprints" aria-label="Permalink to &quot;Editing Blueprints&quot;">​</a></h3><p>To edit an existing blueprint:</p><ol><li>Click anywhere on the blueprint row in the table</li><li>The Blueprint Editor dialog will open with the blueprint&#39;s current settings</li><li>Make necessary changes across the available tabs</li><li>Click &quot;Save&quot; to update the blueprint</li><li>The updated blueprint information will reflect in the list</li></ol><h3 id="unsaved-changes-handling" tabindex="-1">Unsaved Changes Handling <a class="header-anchor" href="#unsaved-changes-handling" aria-label="Permalink to &quot;Unsaved Changes Handling&quot;">​</a></h3><p>The system protects against accidental loss of blueprint changes:</p><ol><li>When you make changes to a blueprint, the system tracks them</li><li>If you attempt to close the Blueprint Editor with unsaved changes: <ul><li>A confirmation dialog appears</li><li>You can choose to leave and discard changes</li><li>Or cancel and return to save your changes</li></ul></li><li>This ensures important configuration changes aren&#39;t lost accidentally</li></ol><h2 id="blueprint-operations" tabindex="-1">Blueprint Operations <a class="header-anchor" href="#blueprint-operations" aria-label="Permalink to &quot;Blueprint Operations&quot;">​</a></h2><h3 id="exporting-blueprint-list" tabindex="-1">Exporting Blueprint List <a class="header-anchor" href="#exporting-blueprint-list" aria-label="Permalink to &quot;Exporting Blueprint List&quot;">​</a></h3><p>To export the blueprint list to Excel:</p><ol><li>Click the &quot;Export to Excel&quot; button (external link icon in top-right)</li><li>Confirm the export in the dialog that appears</li><li>The browser will download a CSV file</li><li>The export includes all currently visible blueprints (respects active filters)</li></ol><h3 id="refreshing-blueprint-data" tabindex="-1">Refreshing Blueprint Data <a class="header-anchor" href="#refreshing-blueprint-data" aria-label="Permalink to &quot;Refreshing Blueprint Data&quot;">​</a></h3><p>To ensure you&#39;re viewing the most current data:</p><ol><li>Click the &quot;Refresh Data&quot; button (refresh icon in top-right)</li><li>The system will reload all blueprint data from the server</li><li>This is useful after making changes or when multiple administrators are working simultaneously</li></ol><h2 id="blueprint-data-management" tabindex="-1">Blueprint Data Management <a class="header-anchor" href="#blueprint-data-management" aria-label="Permalink to &quot;Blueprint Data Management&quot;">​</a></h2><h3 id="group-associations" tabindex="-1">Group Associations <a class="header-anchor" href="#group-associations" aria-label="Permalink to &quot;Group Associations&quot;">​</a></h3><p>Blueprint access is controlled through group assignments:</p><ol><li>Each blueprint can be assigned to multiple groups</li><li>The table displays assigned groups as avatar circles with group initials</li><li>Up to 3 groups are shown directly in the table</li><li>Additional groups are represented by a &quot;+N&quot; indicator</li><li>Hovering over group avatars shows the full group name</li><li>Clicking the group filter allows filtering by specific group assignment</li></ol><h3 id="understanding-blueprint-metadata" tabindex="-1">Understanding Blueprint Metadata <a class="header-anchor" href="#understanding-blueprint-metadata" aria-label="Permalink to &quot;Understanding Blueprint Metadata&quot;">​</a></h3><p>Each blueprint includes metadata about its creation and updates:</p><ol><li><strong>Author</strong>: The name of the person who last updated the blueprint</li><li><strong>Update Date</strong>: When the blueprint was last changed</li><li>This information helps track changes and responsible parties</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective blueprint management:</p><ol><li><p><strong>Naming Conventions</strong>:</p><ul><li>Use descriptive names that clearly indicate purpose</li><li>Consider including department or function in the name</li><li>Use consistent naming patterns across blueprints</li></ul></li><li><p><strong>Filtering Strategy</strong>:</p><ul><li>Use topic filtering for high-level organization</li><li>Use feature filtering to find special-purpose blueprints</li><li>Combine filters for more precise results</li></ul></li><li><p><strong>Organization</strong>:</p><ul><li>Assign meaningful tags for easier discovery</li><li>Use consistent topic categories across similar blueprints</li><li>Limit home screen and quick list blueprints to essential ones</li></ul></li><li><p><strong>Maintenance</strong>:</p><ul><li>Regularly review disabled blueprints</li><li>Check for outdated or redundant blueprints</li><li>Update descriptions when blueprint functionality changes</li></ul></li><li><p><strong>Access Control</strong>:</p><ul><li>Assign groups strategically based on who needs access</li><li>Review group assignments periodically</li><li>Consider creating specific groups for blueprint access</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Blueprint list is empty</p><ul><li>Check if filters are active (blue filter button indicates active filters)</li><li>Click the &quot;Clear Filters&quot; button to remove all filters</li><li>Refresh the data using the refresh button</li><li>Verify you have permissions to view blueprints</li></ul><p><strong>Issue</strong>: Cannot find a specific blueprint</p><ul><li>Try searching by partial name or description</li><li>Clear all filters and browse the complete list</li><li>Check if the blueprint might be disabled</li><li>Verify the blueprint exists and you have permissions to view it</li></ul><p><strong>Issue</strong>: Blueprint editor won&#39;t close</p><ul><li>You likely have unsaved changes</li><li>Choose to either save your changes or discard them</li><li>If the dialog persists, try refreshing the page (may lose changes)</li></ul><p><strong>Issue</strong>: Group avatars not displaying correctly</p><ul><li>The groups store may need refreshing</li><li>Click the refresh button to reload data</li><li>Check if groups exist in the system</li></ul><p><strong>Issue</strong>: Filter shows no results</p><ul><li>Your filter combination may be too restrictive</li><li>Try removing one filter at a time to see what&#39;s causing the issue</li><li>Verify that blueprints matching your criteria exist</li></ul><p><strong>Issue</strong>: Export not working</p><ul><li>Check browser download settings</li><li>Ensure you have proper permissions</li><li>Try with a smaller dataset by applying filters first</li></ul><hr><p>For additional assistance with blueprint management, please contact your system administrator.</p>',82)]))}const f=i(o,[["render",s]]);export{b as __pageData,f as default};
